import{_ as a,o as e,a as r,d as o}from"./chunks/framework.MWxrmMMs.js";const p=JSON.parse('{"title":"Модпаки","description":"Модпаки в Stuzhik: каталог Modrinth и CurseForge с версией под вашу игру, импорт .stzhk, .mrpack и .zip, экспорт в четыре формата, обновление с превью и откатом, готовые переводы от команды Stuzhik.","frontmatter":{"description":"Модпаки в Stuzhik: каталог Modrinth и CurseForge с версией под вашу игру, импорт .stzhk, .mrpack и .zip, экспорт в четыре формата, обновление с превью и откатом, готовые переводы от команды Stuzhik.","head":[["meta",{"name":"keywords","content":"minecraft модпаки, stuzhik, стужик, установка модпака, экспорт модпака, mrpack, curseforge модпак, обновление модпака, перевод модпака"}]]},"headers":[],"relativePath":"guide/modpacks.md","filePath":"guide/modpacks.md"}'),i={name:"guide/modpacks.md"};function d(n,t,h,s,l,c){return e(),r("div",null,[...t[0]||(t[0]=[o('<h1 id="модпаки" tabindex="-1">Модпаки <a class="header-anchor" href="#модпаки" aria-label="Permalink to &quot;Модпаки&quot;">​</a></h1><p>Модпак ставится как отдельная <a href="/guide/instances.html">сборка</a> и помнит, откуда пришёл: его можно обновлять, сравнивать с другими версиями и передавать друзьям.</p><h2 id="каталог" tabindex="-1">Каталог <a class="header-anchor" href="#каталог" aria-label="Permalink to &quot;Каталог&quot;">​</a></h2><p>Раздел «Модпаки» в боковой панели, вкладки «Поиск», «Из файла», «По ссылке» и «Сравнить».</p><ul><li><strong>Поиск</strong>: Modrinth и CurseForge. Фильтр по версии игры ставит версию пака <strong>для этой версии</strong>, а не самую новую: окно установки заранее показывает, какая версия встанет, и даёт выбрать другую. В списке версий пака есть фильтр по версии игры, каналу и загрузчикам</li><li><strong>Из файла</strong>: <code>.stzhk</code>, <code>.mrpack</code> (Modrinth) или <code>.zip</code> (CurseForge). Файл можно и просто перетащить в окно</li><li><strong>По ссылке</strong>: <code>.stzhk</code> из облачного хранилища</li></ul><p>Пока модпак ставится, окно показывает архив пака одной полосой с размером и скоростью, а файлы игры и модов одним счётчиком. «Отменить» останавливает установку с первой секунды, даже пока качается архив.</p><p>Модпак Modrinth ставится так, как его разметил автор: файл, помеченный «не нужен» на клиенте или на сервере, туда не попадает, а сервер берёт свою часть пака.</p><h2 id="экспорт" tabindex="-1">Экспорт <a class="header-anchor" href="#экспорт" aria-label="Permalink to &quot;Экспорт&quot;">​</a></h2><p>«Экспорт сборки» в меню сборки. Форматы:</p><table tabindex="0"><thead><tr><th>Формат</th><th>Для кого</th></tr></thead><tbody><tr><td>STZHK</td><td>для Stuzhik: ссылки на моды и, по желанию, сами файлы внутри</td></tr><tr><td>Modrinth</td><td>для Prism, MultiMC, Modrinth App</td></tr><tr><td>CurseForge</td><td>для CurseForge App; моды, которых там нет, кладутся в архив файлами</td></tr><tr><td>Универсальный ZIP</td><td>для друзей без лаунчера: все файлы и README с инструкцией</td></tr></tbody></table><p>Перед экспортом можно выбрать, какие моды и файлы не брать.</p><h2 id="update" tabindex="-1">Обновление модпака <a class="header-anchor" href="#update" aria-label="Permalink to &quot;Обновление модпака {#update}&quot;">​</a></h2><p>Вкладка «Модпак» на странице сборки. «Проверить обновления» находит новую версию, «Показать изменения» открывает «Что изменится»: какие моды добавятся, обновятся и уйдут. Ваши собственные моды отмечены отдельно («Ваши моды — не трогаем»).</p><ul><li>«Сделать бэкап перед обновлением», «Сохранить мои моды», «Перезаписать конфиги»: по выбору</li><li>«Обновить» обновляет эту сборку, «Установить отдельно» ставит новую версию рядом</li><li><strong>Обновление считается по сборке</strong>: «Доступны новые версии» говорит только о версиях пака для той же версии Minecraft и того же загрузчика. Более новые версии под другую игру или загрузчик показаны отдельной строкой: выбрать их в списке можно, но это переход, а не обновление</li><li><strong>Мод пака, обновлённый вами вручную</strong>, при обновлении пака заменяется его версией из пака, а не остаётся рядом (две копии одного мода роняли игру). Чтобы оставить свою, закрепите версию мода («Закрепить версию»)</li><li><strong>Выключенные моды остаются выключенными</strong>: новая версия такого мода тоже ставится выключенной. На сервере клиентские моды после обновления снова отключаются</li><li><strong>Новая версия пака для другой версии Minecraft</strong>: перед обновлением лаунчер сохраняет всю сборку вместе с мирами, даже если бэкапы выключены. Пока вы не нажали «Оставить», кнопка «Откатить» на странице сборки возвращает файлы, миры, моды и номер версии пака, как при <a href="/guide/instances.html#version-change">смене версии игры</a></li></ul><p><strong>«Вернуть как в паке»</strong> сравнивает папку модов с версией пака, которая стоит, и возвращает её: удалённые моды пака скачиваются снова, изменённые файлы и моды, переставленные на другую версию, заменяются файлами пака. По выбору: включить выключенные моды пака, убрать свои моды, вернуть конфиги пака. Окно показывает всё это до того, как что-то изменится, бэкап делается по умолчанию.</p><p>Сервер из модпака на Linux без окна обновляется командой <code>stuzhik-cli update</code>, подробнее в <a href="/guide/cli.html">консольной версии</a>.</p><h2 id="переводы-от-команды-stuzhik" tabindex="-1">Переводы от команды Stuzhik <a class="header-anchor" href="#переводы-от-команды-stuzhik" aria-label="Permalink to &quot;Переводы от команды Stuzhik&quot;">​</a></h2><p>Команда Stuzhik переводит модпаки на русский сама, без машинного перевода. Лаунчер узнаёт у нашего сервера, какие паки уже переведены, и накладывает перевод сам после установки и обновления сборки. Список пополняется: переведённый пак подхватится без обновления лаунчера. «Спрашивать» или выключить можно в «Настройки → Моды → Переводы сборок». Снятый вручную перевод сам не возвращается, а свой файл перевода лаунчер не заменяет. Перевести сборку самому: <a href="/guide/instances.html#build-translation">Сборки → Перевод сборки</a>.</p><h2 id="сравнение" tabindex="-1">Сравнение <a class="header-anchor" href="#сравнение" aria-label="Permalink to &quot;Сравнение&quot;">​</a></h2><p>Вкладка «Сравнить» в «Модпаках» сравнивает два модпака: файл, сборку или пак из каталога нужной версии. Видно моды, которые есть только в одном, моды с разными версиями и различия в конфигах и других файлах.</p><h2 id="передать-друзьям" tabindex="-1">Передать друзьям <a class="header-anchor" href="#передать-друзьям" aria-label="Permalink to &quot;Передать друзьям&quot;">​</a></h2><p>Через <a href="/guide/connect.html#transfer">Stuzhik Connect</a>: вы открываете сборку друзьям, друг забирает её у себя, файлы идут напрямую. Без Connect экспортируйте в <code>.stzhk</code> и отправьте файл как угодно: друг импортирует его во вкладке «Из файла».</p><h2 id="если-что-то-не-так" tabindex="-1">Если что-то не так <a class="header-anchor" href="#если-что-то-не-так" aria-label="Permalink to &quot;Если что-то не так&quot;">​</a></h2><p><strong>Установка идёт слишком долго.</strong> Её можно остановить кнопкой «Отменить» в окне установки, с первой секунды.</p><p><strong>Игра упала после установки.</strong> <a href="/guide/log-analyzer.html">Анализатор логов</a> назовёт причину и предложит, что сделать.</p>',25)])])}const g=a(i,[["render",d]]);export{p as __pageData,g as default};
